// Kapso agrupa mensajes (búfer): body.data = [ { message, conversation, phone_number_id }, ... ]
// Valida origen, ignora salientes y junta el lote en una sola entrada para el agente.
const PERMITIDO = 'TU_PHONE_NUMBER_ID'; // phone_number_id del negocio
const body = $json.body ?? $json;
const items = Array.isArray(body.data) ? body.data : [body];
const textos = [], ids = [];
let from = '', pnid = '', nombre = '';

for (const it of items) {
  const msg = it.message ?? {};
  if (msg.kapso?.direction && msg.kapso.direction !== 'inbound') continue;
  const p = String(it.phone_number_id || it.conversation?.phone_number_id || '');
  if (p && p !== PERMITIDO) continue;
  pnid = p || pnid;
  from = msg.from || it.conversation?.phone_number || from;
  nombre = it.conversation?.contact_name || nombre;
  if (msg.id) ids.push(String(msg.id));
  const t = String(msg.text?.body || msg.kapso?.content || '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '').trim().slice(0, 1000);
  if (t) textos.push(t);
  else if (msg.type) textos.push('[El cliente envió un mensaje de tipo "' + msg.type + '" que no puedo leer]');
}

const to = String(from).replace(/\D/g, '');
if (!to || textos.length === 0) return [];

return [{ json: {
  text: textos.join('\n').slice(0, 3000),
  to, nombre: String(nombre).slice(0, 80),
  phoneNumberId: pnid || PERMITIDO,
  message_id: ids[ids.length - 1] || ('sin-id-' + $execution.id),
  message_ids: ids
} }];

// Texto para el agente: el lote original o los mensajes que llegaron mientras respondía.
const p = $input.first().json.pendientes;
const texto = Array.isArray(p) && p.length ? p.join('\n') : $('Normalizar mensaje').first().json.text;
return [{ json: { texto } }];

// CONFIGURACIÓN DEL NEGOCIO (editar aquí)
const TZ = 'America/Guayaquil';
// Horario por día: bloques [inicio, fin) en horas. Día sin bloques = cerrado.
// Horario de EliDental publicado en Instagram (21/9/2024): L-V 09:00-18:00, sábado 09:00-15:00.
const HORARIO = {
  lunes: [[9, 18]],
  martes: [[9, 18]],
  'miércoles': [[9, 18]],
  jueves: [[9, 18]],
  viernes: [[9, 18]],
  'sábado': [[9, 15]],
  domingo: []
};
const MAX_DIAS = 60;
// Servicios de EliDental (Loja). precio: null = la doctora lo confirma en la consulta.
const SERVICIOS = [
  { nombre: 'Consulta de valoración', precio: null },
  { nombre: 'Limpieza dental', precio: null },
  { nombre: 'Resina (calza)', precio: null },
  { nombre: 'Control de ortodoncia', precio: null },
  { nombre: 'Urgencia dental', precio: null }
];

const inp = $('Agenda (entrada interna)').first().json;
const fail = (error, mensaje) => [{ json: { valido: false, ok: false, error, mensaje } }];
const accion = String(inp.accion || 'turnos').trim().toLowerCase();
if (!['turnos', 'reservar'].includes(accion)) return fail('ACCION_INVALIDA', 'accion debe ser turnos o reservar');

const fecha = String(inp.fecha || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) return fail('FECHA_INVALIDA', 'La fecha debe tener formato YYYY-MM-DD');
const dia = DateTime.fromISO(fecha, { zone: TZ });
if (!dia.isValid) return fail('FECHA_INVALIDA', 'Esa fecha no existe');
const hoy = DateTime.now().setZone(TZ).startOf('day');
if (dia < hoy) return fail('FECHA_PASADA', 'Esa fecha ya pasó');
if (dia > hoy.plus({ days: MAX_DIAS })) return fail('FECHA_MUY_LEJANA', 'Solo agendamos hasta ' + MAX_DIAS + ' días adelante');
const nombreDia = ['lunes','martes','miércoles','jueves','viernes','sábado','domingo'][dia.weekday - 1];
const bloques = HORARIO[nombreDia] || [];
if (!bloques.length) return fail('DIA_CERRADO', 'El ' + nombreDia + ' no atendemos');
const APERTURA = Math.min(...bloques.map(b => b[0]));
const CIERRE = Math.max(...bloques.map(b => b[1]));

let servicio = null, hora = '', nombre = '';
if (accion === 'reservar') {
  const q = String(inp.servicio || '').trim().toLowerCase();
  servicio = SERVICIOS.find(s => s.nombre.toLowerCase() === q) || SERVICIOS.find(s => q && (s.nombre.toLowerCase().includes(q) || q.includes(s.nombre.toLowerCase())));
  if (!servicio) return fail('SERVICIO_INVALIDO', 'Servicios: ' + SERVICIOS.map(s => s.nombre).join(', '));
  hora = String(inp.hora || '').trim().slice(0, 5);
  if (/^\d:\d{2}$/.test(hora)) hora = '0' + hora;
  if (!/^([01]\d|2[0-3]):00$/.test(hora)) return fail('HORA_INVALIDA', 'La hora debe ser en punto, formato HH:00 (24h)');
  nombre = String(inp.nombre || '').trim().slice(0, 80);
  if (nombre.length < 2) return fail('FALTA_NOMBRE', 'Falta el nombre del paciente');
}

return [{ json: {
  valido: true, accion, fecha, dia: nombreDia, apertura: APERTURA, cierre: CIERRE, bloques,
  desde: dia.set({ hour: APERTURA }).toISO(), hasta: dia.set({ hour: CIERRE }).toISO(),
  hora, nombre, servicio: servicio?.nombre || '', precio: servicio?.precio ?? null,
  telefono: String(inp.telefono || '').replace(/\D/g, '')
} }];

// Turnos de 1 hora dentro de los bloques del día (Validar pedido) que no chocan con Google Calendar.
const TZ = 'America/Guayaquil';
const req = $('Validar pedido').first().json;
const dia = DateTime.fromISO(req.fecha, { zone: TZ });
const minimo = DateTime.now().setZone(TZ).plus({ minutes: 15 });

const ocupados = [];
for (const it of $input.all()) {
  const ev = it.json || {};
  if (!ev.start || ev.status === 'cancelled' || ev.transparency === 'transparent') continue;
  const ini = ev.start.dateTime ? DateTime.fromISO(ev.start.dateTime) : DateTime.fromISO(ev.start.date, { zone: TZ });
  const fin = ev.end?.dateTime ? DateTime.fromISO(ev.end.dateTime) : DateTime.fromISO(ev.end?.date || ev.start.date, { zone: TZ }).plus(ev.end?.date ? {} : { days: 1 });
  if (ini.isValid && fin.isValid) ocupados.push([ini, fin]);
}

const manana = [], tarde = [], libres = [];
for (let h = req.apertura; h < req.cierre; h++) {
  const t = dia.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
  const f = t.plus({ hours: 1 });
  if (!req.bloques.some(([a, b]) => h >= a && h + 1 <= b)) continue; // fuera de horario (p. ej. almuerzo)
  if (t < minimo) continue;
  if (ocupados.some(([a, b]) => t < b && f > a)) continue;
  libres.push(t.toFormat('HH:mm'));
  (h < 12 ? manana : tarde).push(t.toFormat('HH:mm') + ' - ' + f.toFormat('HH:mm'));
}

const base = { fecha: req.fecha, dia: req.dia, manana, tarde };
if (req.accion === 'turnos') {
  return [{ json: { ok: true, crear: false, ...base, total: libres.length,
    mensaje: libres.length ? 'Turnos libres de 1 hora' : 'No hay turnos libres ese día' } }];
}
if (!libres.includes(req.hora)) {
  return [{ json: { ok: false, crear: false, error: 'HORA_NO_DISPONIBLE', ...base,
    mensaje: 'Esa hora ya no está libre. Ofrece otra de manana/tarde.' } }];
}
const inicio = dia.set({ hour: Number(req.hora.slice(0, 2)), minute: 0 });
return [{ json: { ok: true, crear: true, fecha: req.fecha, dia: req.dia, hora: req.hora,
  inicio: inicio.toISO(), fin: inicio.plus({ hours: 1 }).toISO(),
  titulo: '🦷 ' + req.servicio + ' - ' + req.nombre,
  descripcion: 'Paciente: ' + req.nombre + '\nTel: ' + req.telefono + '\nServicio: ' + req.servicio + (req.precio != null ? ' ($' + req.precio + ')' : '') + '\nAgendado por WhatsApp (Eli)',
  servicio: req.servicio, precio: req.precio, nombre: req.nombre } }];

// Evento para Eli → CRM. Si algo falta, no manda nada.
const n = $('Normalizar mensaje').first().json;
if (!n.to || !n.message_id) return [];
return [{ json: { tipo: 'mensaje_entrante', telefono: n.to, nombre_whatsapp: n.nombre || undefined, message_id: n.message_id, texto: n.text, en: new Date().toISOString() } }];

// Respuesta que Eli acaba de mandar. execution_id lleva el número de vuelta para que cada respuesta del bucle sea única.
const n = $('Normalizar mensaje').first().json;
const salida = $('Agente version4').last().json.output;
if (!n.to || !salida) return [];
return [{ json: { tipo: 'mensaje_saliente', telefono: n.to, texto: String(salida).slice(0, 3000), execution_id: $execution.id + '-' + $runIndex, en: new Date().toISOString() } }];

// Cita creada en Google Calendar (Crear evento devuelve el id del evento).
const r = $('Validar pedido').first().json;
const c = $('Calcular turnos (mañana / tarde)').first().json;
const ev = $input.first().json;
if (!ev.id || !r.telefono) return [];
return [{ json: { tipo: 'cita_reservada', telefono: r.telefono, gcal_event_id: ev.id, inicio: c.inicio, fin: c.fin, servicio: c.servicio, nombre: c.nombre } }];
